public static class TextExtensions
{
    public static bool IsPalindrome(this string text)
    {
        var chars = text.Where(char.IsLetterOrDigit).Select(char.ToLowerInvariant).ToArray();
        for (int i = 0, j = chars.Length - 1; i < j; i++, j--)
        {
            if (chars[i] != chars[j]) return false;
        }
        return true;
    }

    public static int WordCount(this string text) =>
        text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

    public static string Abbreviate(this string text, int max)
    {
        if (text.Length <= max) return text;
        string[] words = text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        var sb = new StringBuilder();
        foreach (string w in words)
        {
            int needed = (sb.Length == 0 ? 0 : 1) + w.Length;
            if (sb.Length + needed + 3 > max) break;
            if (sb.Length > 0) sb.Append(' ');
            sb.Append(w);
        }
        if (sb.Length == 0) return text[..Math.Max(0, max - 3)] + "...";
        return sb + "...";
    }

    public static double Median(this IEnumerable<int> values)
    {
        var sorted = values.Order().ToList();
        if (sorted.Count == 0) throw new InvalidOperationException("no values");
        int mid = sorted.Count / 2;
        return sorted.Count % 2 == 1 ? sorted[mid] : (sorted[mid - 1] + (double)sorted[mid]) / 2;
    }
}

public static class Ids
{
    private static readonly Dictionary<string, int> _counters = new();

    public static string Next(string prefix)
    {
        int n = _counters.GetValueOrDefault(prefix) + 1;
        _counters[prefix] = n;
        return $"{prefix}-{n}";
    }

    public static void Reset() => _counters.Clear();
}

unitTests:
Test("palindromes", () =>
{
    CheckEq("A man, a plan, a canal: Panama".IsPalindrome(), true);
    CheckEq("racecar".IsPalindrome(), true);
    CheckEq("hello".IsPalindrome(), false);
    CheckEq("".IsPalindrome(), true);
    CheckEq("No 'x' in Nixon".IsPalindrome(), true);
});

Test("word counts", () =>
{
    CheckEq("  the quick\tbrown\nfox ".WordCount(), 4);
    CheckEq("".WordCount(), 0);
});

Test("abbreviating", () =>
{
    CheckEq("short".Abbreviate(10), "short");
    CheckEq("The quick brown fox jumps".Abbreviate(18), "The quick brown...");
    CheckEq("The quick brown fox jumps".Abbreviate(17), "The quick...");
    CheckEq("Supercalifragilistic".Abbreviate(10), "Superca...");
    CheckEq("a  b   c d e f".Abbreviate(9), "a b c...");
});

Test("medians", () =>
{
    CheckNear(new[] { 5, 1, 3 }.Median(), 3);
    CheckNear(new List<int> { 4, 1, 3, 2 }.Median(), 2.5);
    CheckNear(new[] { int.MaxValue, int.MaxValue }.Median(), int.MaxValue);
    CheckThrows<InvalidOperationException>(() => Array.Empty<int>().Median());
});

Test("ids per prefix", () =>
{
    Ids.Reset();
    CheckEq(Ids.Next("order"), "order-1");
    CheckEq(Ids.Next("order"), "order-2");
    CheckEq(Ids.Next("user"), "user-1");
    Ids.Reset();
    CheckEq(Ids.Next("order"), "order-1");
});

